-- 13_pr_recap_sep_okt.sql — SEPTEMBER rows 103–118, the OKTOBER PR RECAP tab,
-- and the payments step 11 could not find yet.
--
-- GENERATED by `13_pr_sheet.py` from `13_pr_rows.py`. Edit those, not this.
--
-- What it writes, all inside one DO block so it lands whole or not at all:
--
--   ops_procure.pr_documents     one per request date, numbered after whatever
--                                that day already holds (`ops_core.doc_numbers`)
--   ops_procure.pr_lines         the sheet rows the web app does not already hold
--   ops_procure.pr_approvals     GOODS, by EJO, dated the day the ledger paid it —
--                                only where the line has no approval yet
--   ops_acct.payment_allocations the ledger transaction(s) that paid each line:
--                                this is the PR ID on the ledger row
--                                (`v_transaction.pr_line_nos`)
--   ops_core.legacy_map          `sheet.pr_recap` (row → line) and
--                                `sheet.pr_recap.payment` (row → transaction)
--
-- It creates and changes no ledger transaction, and it refuses (rolls back)
-- if any transaction would end up allocated beyond its amount.

do $import$
declare
  v_shared uuid := (select id from ops_core.users where email = 'shared@talaliving.com');
  v_it     uuid := (select id from ops_core.users where email = 'it@talaliving.com');
  v_evin   uuid := (select id from ops_core.users where email = 'evin@talaliving.com');
  v_run    uuid := gen_random_uuid();
  v_bad    text;
begin
  create temp table _rows (
    ref text primary key, web_line text, day date, requester text, project text,
    description text not null, qty numeric, uom text, unit_price numeric, item_total numeric not null,
    vendor_raw text, category ops_procure.pr_category_t, purpose text, paid numeric, note text
  ) on commit drop;

  create temp table _alloc (ref text, trx_no text, amount numeric, how text) on commit drop;

  -- every transaction named must be in the ledger and not void
  select string_agg(distinct a.trx_no, ', ') into v_bad
    from _alloc a
   where not exists (select 1 from ops_acct.transactions t where t.trx_no = a.trx_no and t.status <> 'VOID');
  if v_bad is not null then
    raise exception 'allocation names a transaction that is not in the ledger: %', v_bad;
  end if;

  -- the line each sheet row lands on: the web app's, step 11's, or a new one
  create temp table _target on commit drop as
  select r.ref, coalesce(w.id, m.target_id) as line_id
    from _rows r
    left join ops_procure.pr_lines w on w.line_no_full = r.web_line
    left join ops_core.legacy_map m on m.source_table = 'sheet.pr_recap' and m.source_id = r.ref;
  select a.ref, m.target_id from (select distinct ref from _alloc) a
    join ops_core.legacy_map m on m.source_table = 'sheet.pr_recap' and m.source_id = a.ref
   where not exists (select 1 from _target t where t.ref = a.ref);

  select string_agg(r.ref, ', ') into v_bad
    from _rows r join _target t using (ref) where r.web_line is not null and t.line_id is null;
  if v_bad is not null then
    raise exception 'web line named for % does not exist', v_bad;
  end if;
  select string_agg(distinct a.ref, ', ') into v_bad
    from _alloc a where not exists (select 1 from _rows r where r.ref = a.ref)
                    and not exists (select 1 from _target t where t.ref = a.ref and t.line_id is not null);
  if v_bad is not null then
    raise exception 'payment for a sheet row that maps to no line: %', v_bad;
  end if;

  create temp table _paid_on on commit drop as
  select a.ref, min(t.trx_date) as day
    from _alloc a join ops_acct.transactions t on t.trx_no = a.trx_no and t.status <> 'VOID'
   group by a.ref;

  -- ── new lines ─────────────────────────────────────────────────────────
  create temp table _new on commit drop as
  select r.*,
         coalesce((select u.id from ops_core.users u where u.email = r.requester), v_shared) as requested_by,
         (select p.id from ops_procure.projects p where upper(p.name) = r.project) as project_id,
         coalesce(
           (select v.id from ops_procure.vendors v
             where v.merged_into is null
               and (upper(btrim(v.name)) = upper(btrim(r.vendor_raw))
                    or upper(btrim(r.vendor_raw)) = any (select upper(btrim(x)) from unnest(v.aka) x))
             order by v.code limit 1),
           (select min(v.id::text)::uuid from ops_procure.vendors v
             where v.merged_into is null
               and regexp_replace(upper(v.name), '[^A-Z0-9]', '', 'g')
                 = regexp_replace(upper(r.vendor_raw), '[^A-Z0-9]', '', 'g')
            having count(*) = 1)) as vendor_id,
         (select u.code from ops_procure.uom u where u.code = r.uom) as uom_ok,
         row_number() over (partition by r.day order by left(r.ref, 3) desc, substring(r.ref from 4)::int) as line_no,
         null::text as doc_no
    from _rows r join _target t using (ref)
   where t.line_id is null;

  -- one document per request date, numbered after what the day already has
  with days as (
    select n.day,
           greatest(coalesce((select d.seq from ops_core.doc_numbers d where d.prefix = 'pr' and d.day = n.day), 0),
                    coalesce((select max(split_part(p.doc_no, '_', 2)::int) from ops_procure.pr_documents p
                               where p.doc_no like 'pr-' || to_char(n.day, 'YY-MM-DD') || '\_%'), 0)) + 1 as seq
      from (select distinct day from _new) n)
  update _new n set doc_no = 'pr-' || to_char(n.day, 'YY-MM-DD') || '_' || lpad(d.seq::text, 2, '0')
    from days d where d.day = n.day;

  select n.doc_no, 'PR', 'SUBMITTED',
         (array_agg(n.requested_by order by n.line_no))[1],
         case when count(distinct n.project_id) = 1 and count(*) = count(n.project_id)
              then min(n.project_id::text)::uuid end,
         (n.day + time '09:00') at time zone 'Asia/Jakarta',
         (n.day + time '09:00') at time zone 'Asia/Jakarta'
    from _new n group by n.doc_no, n.day;

  select 'pr', n.day, max(split_part(n.doc_no, '_', 2)::int) from _new n group by n.day
  on conflict (prefix, day) do update set seq = greatest(ops_core.doc_numbers.seq, excluded.seq);

  select d.id, n.doc_no, n.line_no, n.description, n.qty, n.uom_ok, n.unit_price, n.item_total,
         n.vendor_id, n.category, n.purpose, (n.day + time '09:00') at time zone 'Asia/Jakarta'
    from _new n join ops_procure.pr_documents d on d.doc_no = n.doc_no;

  update _target t set line_id = l.id
    from _new n join ops_procure.pr_lines l on l.doc_no = n.doc_no and l.line_no = n.line_no
   where t.ref = n.ref;

  -- ── approvals: GOODS, by EJO, on the day it was paid ──────────────────
  select l.id, 'GOODS', true, l.qty, l.item_total, v_evin, 'evin@talaliving.com',
         (coalesce(p.day, r.day) + time '12:00') at time zone 'Asia/Jakarta', 'sheet'
    from _rows r
    join _target t using (ref)
    join ops_procure.pr_lines l on l.id = t.line_id
    left join _paid_on p using (ref)
   where l.removed_at is null
     and not exists (select 1 from ops_procure.pr_approvals a where a.line_id = l.id);

  -- ── payments: the PR ID on the ledger row ─────────────────────────────
  with todo as (
    select a.ref, a.trx_no, a.amount, a.how, x.id as trx_id, l.line_no_full,
           case when ac.code = 'PETTY CASH' then 'cash' else 'transfer' end::ops_acct.alloc_method_t as method
      from _alloc a
      join _target t on t.ref = a.ref
      join ops_procure.pr_lines l on l.id = t.line_id
      join ops_acct.transactions x on x.trx_no = a.trx_no and x.status <> 'VOID'
      join ops_acct.accounts ac on ac.id = x.account_id
     where not exists (select 1 from ops_core.legacy_map m
                        where m.source_table = 'sheet.pr_recap.payment' and m.source_id = a.ref || ' → ' || a.trx_no)
  ), ins as (
    select trx_id, line_no_full, amount, method, v_it from todo
    returning id, trx_id, pr_line_no
  )
  select 'sheet.pr_recap.payment', d.ref || ' → ' || d.trx_no, 'ops_acct.payment_allocations', i.id,
         'imported', 'read by hand: ' || d.how, v_run
    from ins i join todo d on d.trx_id = i.trx_id and d.line_no_full = i.pr_line_no;

  -- ── the map: every sheet row, and what it became ──────────────────────
  select 'sheet.pr_recap', r.ref, 'ops_procure.pr_lines', t.line_id, 'imported',
         nullif(concat_ws('; ',
           case when r.web_line is not null then 'already in the web app as ' || r.web_line end,
           'approved = paid ' || to_char(coalesce(p.day, r.day), 'DD Mon YYYY') || ' (owner, 2026-11-11)',
           case when n.vendor_raw is not null and n.vendor_id is null
                then 'vendor ' || quote_literal(n.vendor_raw) || ' resolves to nothing' end,
           case when n.project is not null and n.project_id is null
                then 'project ' || quote_literal(n.project) || ' is not a project here' end,
           r.note), ''),
         v_run
    from _rows r join _target t using (ref)
    left join _new n using (ref)
    left join _paid_on p using (ref)
  on conflict (source_table, source_id) do nothing;

  -- ── no transaction may be allocated beyond its amount ─────────────────
  select string_agg(trx_no || ' (' || amount_idr || ' < ' || allocated || ')', ', ') into v_bad
    from (select t.trx_no, t.amount_idr, sum(a.amount) as allocated
            from ops_acct.payment_allocations a join ops_acct.transactions t on t.id = a.trx_id
           where a.superseded_by is null and t.trx_no in (select trx_no from _alloc)
           group by t.trx_no, t.amount_idr
          having sum(a.amount) > t.amount_idr) o;
  if v_bad is not null then
    raise exception 'over-allocated: %', v_bad;
  end if;

  raise notice 'run %: % new lines in % documents, % allocations',
    v_run, (select count(*) from _new), (select count(distinct doc_no) from _new),
    (select count(*) from ops_core.legacy_map where run_id = v_run and source_table = 'sheet.pr_recap.payment');
end
$import$;
